print("Welcome to the Tip Calculator!")bill = float(input("What was the total bill? $"))tip = int(input("How much tip would you like to give? 10, 12, or 15? "))number_of_people = int(input("How many people to split the bill? "))bill_per_person = round((bill + (bill * tip / 100)) / number_of_people, 2)print(f"Each person should pay ${bill_per_person}")